-- Migration 012: Record when a candidate entered their current stage.
ALTER TABLE applicants ADD COLUMN IF NOT EXISTS stage_changed_at TIMESTAMP WITH TIME ZONE;
UPDATE applicants SET stage_changed_at = COALESCE(created_at, NOW()) WHERE stage_changed_at IS NULL;
ALTER TABLE applicants ALTER COLUMN stage_changed_at SET DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE applicants ALTER COLUMN stage_changed_at SET NOT NULL;

-- These links were generated by the old interview form and never pointed at a real meeting.
UPDATE applicants SET meet_link = NULL WHERE meet_link ~ 'meet\.google\.com/fem-';

-- A trigger covers every route that moves a candidate, including imports and promotion.
CREATE OR REPLACE FUNCTION touch_applicant_stage_time() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.stage IS DISTINCT FROM OLD.stage THEN
    NEW.stage_changed_at := NOW();
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS applicant_stage_time ON applicants;
CREATE TRIGGER applicant_stage_time BEFORE UPDATE ON applicants
FOR EACH ROW EXECUTE FUNCTION touch_applicant_stage_time();
